from PIL import Image
import glob

def stats(pattern, name):
    files = sorted(glob.glob(pattern))
    lums, colors = [], []
    for f in files:
        try:
            im = Image.open(f).convert('RGB').resize((64,36))
        except Exception:
            continue
        px = list(im.getdata()); n = len(px)
        a = tuple(sum(p[i] for p in px)/n for i in range(3))
        colors.append(a); lums.append(0.299*a[0]+0.587*a[1]+0.114*a[2])
    sp = [max(c)-min(c) for c in colors]
    bright = sum(1 for l in lums if l>120)
    print(f"{name}: n={len(lums)} meanLum={sum(lums)/len(lums):.1f} max={max(lums):.1f} "
          f"spread={sum(sp)/len(sp):.1f} >120lum={bright}")
    return colors, lums

def bar(colors, name):
    H=40
    out = Image.new('RGB',(len(colors),H)); p=out.load()
    for x,c in enumerate(colors):
        for y in range(H): p[x,y]=tuple(int(v) for v in c)
    out.resize((len(colors)*10,H*4), Image.NEAREST).save(f'/tmp/{name}_sampled.png')

for key in ["arlington","transsiberian","badlt"]:
    c,l = stats(f'/tmp/sets/{key}_*.jpg', key)
    bar(c, key+"_set")
